/// <returns>Sales order type Id.</returns>
[DataMember,
 SysOperationDisplayOrder('1')]
public METSalesOrderTypeID parmOrderTypeId(METSalesOrderTypeID _orderTypeId = orderTypeId)
{
    orderTypeId = _orderTypeId;
    return orderTypeId;
}

