/// <summary>
/// Gets/set packed query.
/// </summary>
/// <param name = "_packedQuery">Packed query.</param>
/// <returns>Packed query.</returns>
[
    DataMemberAttribute,
    AifQueryTypeAttribute('_packedQuery', queryStr(METReserveEventOrdersQuery))
]
public str parmPackedQuery(str _packedQuery = packedQuery)
{
    packedQuery = _packedQuery;
    return packedQuery;
}

/// <summary>
/// Method to get query object from packedQuery
/// </summary>
/// <returns><c>Query</c> object from packedQuery</returns>
public Query getQuery()
{
    return new Query(SysOperationHelper::base64Decode(packedQuery));
}

/// <summary>
/// Initiazes data variables.
/// </summary>
public void initialize()
{
    QueryBuildDataSource qbds;
    QueryBuildRange      qbr;
    QueryFilter          qf;
    Query                query;
    date                 todayDate;

    todayDate = DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone());
    query = this.getQuery();
    qbds = query.dataSourceTable(tableNum(METSalesTable));

    if (qbds)
    {
        qbr = SysQuery::findOrCreateRange(qbds, fieldNum(METSalesTable,EventId));
        qbr.value(SysQuery::valueNotEmptyString());

        //Fixed range to restrict records with dateNull() value.
        qbr = SysQuery::findOrCreateRange(qbds, fieldNum(METSalesTable, OrderReleaseDate));
        qbr.value(SysQuery::valueNot(dateNull()));
        qbr.status(RangeStatus::Locked);

        //Query filter provides user with option on UI to select any range for the OrderReleaseDate.
        qf = SysQuery::findOrCreateQueryFilter(query, qbds, fieldStr(METSalesTable, OrderReleaseDate));
        qf.value(SysQueryRangeUtil::metLessThanEqualDate(todayDate));
    }

    this.parmPackedQuery(SysOperationHelper::base64Encode(query.pack()));
}

/// <summary>
/// Initializes query.
/// </summary>
/// <returns>
/// <c>Query</c>.
/// </returns>
public Query initQuery()
{
    QueryBuildDataSource qbds;
    Query                query;

    void addRangesFromList(List _list, FieldId _fieldId)
    {
        ListEnumerator enum;

        enum = _list.getEnumerator() as ListEnumerator;

        while (enum && enum.moveNext())
        {
            qbds.addRange(_fieldId).value(enum.current());
        }
    }

    query = this.getQuery();
    qbds = query.dataSourceTable(tableNum(SalesLine));

    if (qbds)
    {
        addRangesFromList(salesIdList, fieldNum(SalesLine, SalesId));
        addRangesFromList(itemIdList, fieldNum(SalesLine, ItemId));
    }

    if (orderTypeId)
    {
        qbds = query.dataSourceTable(tableNum(METSalesOrderTypes));

        if (qbds)
        {
            SysQuery::findOrCreateRange(qbds, fieldNum(METSalesOrderTypes, SalesOrderTypeID)).value(queryValue(orderTypeId));
        }
    }

    return query;
}
